package util;import org.junit.jupiter.api.DisplayName;import org.junit.jupiter.api.Test;import static org.junit.jupiter.api.Assertions.*;class StringUtilTest {    @Test    @DisplayName("Обычный случай из условия")    void reverse_only_letters_in_mixed_string() {        assertEquals("t@eb eht av$J!123", StringUtil.reverseLetters("J@va the be$t!123"));    }    @Test    @DisplayName("Пустая строка возвращает пустую строку")    void return_empty_for_empty_string() {        assertEquals("", StringUtil.reverseLetters(""));    }    @Test    @DisplayName("Одна буква остается как есть")    void return_same_single_letter_when_input_is_one_letter() {        assertEquals("a", StringUtil.reverseLetters("a"));    }    @Test    @DisplayName("Строка без буквы не меняется")    void return_unchanged_string_when_there_are_no_letters_in_input() {        assertEquals("!!111", StringUtil.reverseLetters("!!111"));    }    @Test    @DisplayName("Только буквы — обычный разворот")    void reverse_all_letters_when_input_contains_only_letters() {        assertEquals("dcba", StringUtil.reverseLetters("abcd"));    }    @Test    @DisplayName("Небуквенные символы остаются на своих позициях")    void keep_non_letter_symbols_in_place_when_reversing() {        assertEquals("d!c@b#a", StringUtil.reverseLetters("a!b@c#d"));    }    @Test    @DisplayName("Регистр едет вместе с буквой")    void preserve_letter_case_when_reversing_mixed_case_string() {        assertEquals("olleH", StringUtil.reverseLetters("Hello"));    }    @Test    @DisplayName("null возвращается как null (без NPE)")    void return_null_when_input_string_is_null() {        assertNull(StringUtil.reverseLetters(null));    }}